#include <stdio.h>
#include <stdlib.h>

static char inbuf[1 << 20];
static int inpos = 0, inlen = 0;

static inline int getch(void) {
    if (inpos >= inlen) {
        inlen = fread(inbuf, 1, sizeof(inbuf), stdin);
        inpos = 0;
        if (inlen == 0) return EOF;
    }
    return (unsigned char)inbuf[inpos++];
}

static int readInt(void) {
    int c = getch();
    while (c <= ' ' && c != EOF) c = getch();
    int x = 0;
    while (c > ' ') {
        x = x * 10 + (c - '0');
        c = getch();
    }
    return x;
}

static char readOp(void) {
    int c = getch();
    while (c <= ' ' && c != EOF) c = getch();
    return (char)c;
}

static char outbuf[1 << 20];
static int outpos = 0;

static void flushOut(void) {
    fwrite(outbuf, 1, outpos, stdout);
    outpos = 0;
}

static inline void putChar(char c) {
    if (outpos == (int)sizeof(outbuf)) flushOut();
    outbuf[outpos++] = c;
}

static void writeInt(int x) {
    if (x == 0) {
        putChar('0');
        return;
    }
    char s[16];
    int len = 0;
    while (x > 0) {
        s[len++] = (char)('0' + x % 10);
        x /= 10;
    }
    while (len--) putChar(s[len]);
}

int main(void) {
    int N = readInt();
    int M = readInt();
    int P = readInt();

    int *row = (int *)malloc((size_t)(N + 1) * sizeof(int));
    int *col = (int *)malloc((size_t)(M + 1) * sizeof(int));

    for (int i = 1; i <= N; ++i) row[i] = i;
    for (int j = 1; j <= M; ++j) col[j] = j;

    for (int k = 0; k < P; ++k) {
        char op = readOp();
        int a = readInt();
        int b = readInt();

        if (op == 'L') {
            int tmp = row[a];
            row[a] = row[b];
            row[b] = tmp;
        } else {
            int tmp = col[a];
            col[a] = col[b];
            col[b] = tmp;
        }
    }

    for (int i = 1; i <= N; ++i) {
        int base = (row[i] - 1) * M;
        for (int j = 1; j <= M; ++j) {
            if (j > 1) putChar(' ');
            writeInt(base + col[j]);
        }
        putChar('\n');
    }

    flushOut();
    free(row);
    free(col);
    return 0;
}
